import os
from dataclasses import dataclass, field
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('repo-admin')
API = 'https://api.github.com'
HEADERS = {'Authorization': f"Bearer {os.environ.get('GITHUB_TOKEN', '')}", 'Accept': 'application/vnd.github+json'}

@dataclass
class RemovalResult:
    collaborator_removed: bool = False
    deleted_key_ids: list = field(default_factory=list)
    errors: list = field(default_factory=list)

    def summary(self) -> str:
        return f'collaborator_removed={self.collaborator_removed}, deleted_keys={self.deleted_key_ids}, errors={self.errors}'

def _archive_user_branches(base: str, username: str, result: RemovalResult) -> None:
    # Rename the user's personal branches (username/*) under an archive/ prefix
    resp = requests.get(f'{base}/branches', params={'per_page': 100}, headers=HEADERS, timeout=30)
    if resp.status_code != 200:
        result.errors.append(f'list branches failed: {resp.status_code}')
        return
    for branch in resp.json():
        name = branch['name']
        if name.startswith(f'{username}/'):
            r = requests.post(f'{base}/branches/{name}/rename', json={'new_name': f'archive/{name}'}, headers=HEADERS, timeout=30)
            if r.status_code != 201:
                result.errors.append(f'branch {name} rename failed: {r.status_code}')

@mcp.tool()
def remove_collaborator_and_delete_deploy_keys(owner: str, repo: str, username: str) -> str:
    result = RemovalResult()
    base = f'{API}/repos/{owner}/{repo}'
    keys_resp = requests.get(f'{base}/keys', headers=HEADERS, timeout=30)
    if keys_resp.status_code != 200:
        result.errors.append(f'list keys failed: {keys_resp.status_code}')
    else:
        for key in keys_resp.json():
            if key.get('added_by') != username:
                continue
            resp = requests.delete(f"{base}/keys/{key['id']}", headers=HEADERS, timeout=30)
            if resp.status_code == 204:
                result.deleted_key_ids.append(key['id'])
            else:
                result.errors.append(f"key {key['id']} delete failed: {resp.status_code}")
    resp = requests.delete(f'{base}/collaborators/{username}', headers=HEADERS, timeout=30)
    if resp.status_code == 204:
        result.collaborator_removed = True
    else:
        result.errors.append(f'collaborator removal failed: {resp.status_code}')
    _archive_user_branches(base, username, result)
    return result.summary()
